{
  "quantity": {
    "description": "Change in own-team expected single-game scoring margin from adopting the strategy",
    "units": "points",
    "support": "unbounded real; positive favors own team"
  },
  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Down 14 Go-For-2 in 4th Quarter",
      "recommendation": "When trailing by 14 points in the 4th quarter, go for 2 after scoring the first touchdown.",
      "rationale": "Expected points and win probability models universally agree this increases regulation win probability by setting up a win with a subsequent extra point, while leaving a chance to tie with another 2-point conversion if the first fails. It prevents playing for overtime where win probability reverts to a coin flip.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.15,
          "interval_95_low": -0.05,
          "interval_95_high": 0.35,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The situational frequency is low, resulting in a small average per-game effect that is well-behaved, symmetric, and tightly clustered around a slight positive impact."
        },
        "parameters": {
          "mu": 0.15,
          "sigma": 0.102,
          "conversion_note": "mu = most_plausible = 0.15; sigma = (0.35 - -0.05) / 3.92 = 0.40 / 3.92 = 0.102"
        },
        "consistency_check": "most_plausible_value (0.15) is exactly centered in the [-0.05, 0.35] interval, and normal distribution support covers signed real values."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "High-Frequency Fast At-Snap Motion",
      "recommendation": "Utilize high-speed, horizontal at-snap 'cheat' motion on over 40% of early down passing plays.",
      "rationale": "Public analytics continuously confirm this gives receivers a running start against man coverage and forces zone-match defenders to hesitate, significantly boosting EPA/play without increasing turnover risk.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.2,
          "interval_95_low": 0.0,
          "interval_95_high": 2.4,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "While the average effect is heavily positive, defenses occasionally fail to adapt entirely (fat right tail of blown coverages) or occasionally successfully zero-blitz the motion to disrupt timing (fat left tail)."
        },
        "parameters": {
          "nu": 4,
          "mu": 1.2,
          "sigma": 0.432,
          "conversion_note": "Chose nu = 4 for heavy tails. Critical value t_{0.975,4} = 2.776. mu = most_plausible = 1.2; sigma (scale) = (2.4 - 0.0) / (2 * 2.776) = 2.4 / 5.552 = 0.432"
        },
        "consistency_check": "most_plausible_value (1.2) is exactly centered in the [0.0, 2.4] interval. Support covers unbounded signed reals."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Zero-Blitz Elimination on Early Downs",
      "recommendation": "Drop blitz rates below 15% on 1st and 2nd downs, heavily leaning on two-high coverage shells.",
      "rationale": "Public EPA models overwhelmingly show offenses pass highly efficiently against early-down blitzes, punishing aggressive calls. Limiting explosive passing by forcing underneath throws significantly reduces opponent expected points.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.7,
          "interval_95_low": 0.1,
          "interval_95_high": 1.3,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "A consistent, steady scheme adjustment applied over a large sample of early downs yields a stable, predictable, and moderately distributed scoring suppression."
        },
        "parameters": {
          "mu": 0.7,
          "sigma": 0.306,
          "conversion_note": "mu = most_plausible = 0.7; sigma = (1.3 - 0.1) / 3.92 = 1.2 / 3.92 = 0.306"
        },
        "consistency_check": "most_plausible_value (0.7) is in the precise middle of the [0.1, 1.3] bounds, with normal support covering signed reals."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "Pre-Scripted Go/No-Go 4th Down Embedded Decisions",
      "recommendation": "Embed 4th-down decisions and specific play calls directly into the first 15 scripted plays so the offense can rush the line on 4th down without sideline input.",
      "rationale": "Public analytics evaluate 4th down probabilities in a vacuum but are completely silent on the unmeasurable value of eliminating coaching hesitation and sideline communication lag. My coaching judgment dictates that bypassing the communication chain catches defenses in base sub-packages and eliminates wasted timeouts.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.2,
          "interval_95_low": -0.5,
          "interval_95_high": 1.8,
          "shape": "right_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "Right-skewed because the downside is firmly capped (a standard failed 4th down or burned timeout), while the upside is occasionally catching an unprepared defense for a massive, game-altering touchdown."
        },
        "parameters": {
          "xi": -0.15,
          "omega": 0.7,
          "alpha": 2.5,
          "conversion_note": "Fitted numerically: an alpha of 2.5 pulls the mode to the right of location xi. Setting xi = -0.15 and scale omega = 0.7 places the mode approximately at 0.2 and captures ~95% of the central mass roughly between -0.5 and 1.8."
        },
        "consistency_check": "most_plausible_value (0.2) sits securely inside the asymmetric [-0.5, 1.8] interval. Skew normal covers the entire unbounded real line."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "21 Personnel Pass-First Base Offense",
      "recommendation": "Deploy a true fullback (21 personnel) on over 50% of first downs, but throw the ball 65% of the time from this heavier alignment.",
      "rationale": "While analytics universally agree that passing on early downs is highly efficient, models are silent on true fullbacks because the modern sample size evaporated a decade ago. My intuition is that 21 personnel structurally forces heavy base linebackers onto the field, generating a massive speed mismatch for the passing game.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.0,
          "interval_95_low": -1.5,
          "interval_95_high": 3.5,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "Symmetric with heavy tails due to massive uncertainty. Biting on the fullback could yield wide-open passing lanes (fat right tail), but if defenses simply refuse to respect the FB as a viable threat, we effectively play 10-on-11 (fat left tail)."
        },
        "parameters": {
          "nu": 7,
          "mu": 1.0,
          "sigma": 1.057,
          "conversion_note": "Chose nu = 7 for moderately heavy tails. Critical value t_{0.975,7} = 2.365. mu = most_plausible = 1.0; sigma (scale) = (3.5 - -1.5) / (2 * 2.365) = 5.0 / 4.73 = 1.057"
        },
        "consistency_check": "most_plausible_value (1.0) is the exact midpoint of [-1.5, 3.5], and the t-distribution provides the required unbounded support."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "Mid-Drive D-Line Hockey Shifts",
      "recommendation": "Substitute the entire defensive line simultaneously every 3 to 4 plays during a long sustained opponent drive, disregarding down and distance.",
      "rationale": "Public analytics focus on isolated pass-rush win rates but rarely model the invisible cumulative fatigue of long drives. My intuition is that a completely fresh rotation beats an exhausted elite offensive line, despite this being a weak candidate due to grave logistical risks.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.0,
          "interval_95_low": -2.5,
          "interval_95_high": 1.0,
          "shape": "left_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "Left-skewed to reflect honest weakness: while fresh legs occasionally kill a drive, the severe penalty for a botched mid-drive substitution (12-men on the field yielding a free play) creates a dangerous downside tail."
        },
        "parameters": {
          "xi": 0.4,
          "omega": 1.1,
          "alpha": -3.0,
          "conversion_note": "Fitted numerically: negative alpha (-3.0) forces the mode left of xi. Setting xi = 0.4 and omega = 1.1 positions the mode near 0.0, capturing the 95% interval effectively in [-2.5, 1.0]."
        },
        "consistency_check": "most_plausible_value (0.0) is validly inside the asymmetric bounds [-2.5, 1.0]. Support encompasses signed impacts for a strategy likely hovering near zero with negative skew."
      }
    }
  ]
}
